scwin.__triggerMouseover = function() {
    var el = document.getElementsByClassName('municipality c39')[0];
    scwin.fireMouseHover(el);
};

scwin.fireMouseHover = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
};

scwin.checkTooltipSize = function() {
    const tooltipElement = WebSquare.wUnit.getDomById('mapchart1_tooltip');

    if (!tooltipElement) {
        console.log('ID가 "mf_mapchart1_tooltip"인 요소를 찾을 수 없습니다.');
        return false;
    }

    const rect = tooltipElement.getBoundingClientRect();
    console.log('Top:', rect.top);

    // 맵 크기 451, 툴팁 크기 26
    return rect.top <= 425;
};

scwin.unitTest = function () {
    //Unit 
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__triggerMouseover()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkTooltipSize()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};

scwin.unitTest();
